require_once __DIR__.'/updater.php';
$manager=new SourceUpdater(__DIR__);$pending=null;$pendingError='';
if(!empty($_SESSION['pending_update'])){try{$pending=$manager->pending($_SESSION['pending_update']);}catch(Throwable $exception){$pendingError='بسته قبلی دیگر آماده نصب نیست. فایل ZIP را دوباره بررسی کنید.';unset($_SESSION['pending_update']);}}
$history=$manager->history();
?><div class="admin-panel update-intro"><h3>به‌روزرسانی سایت با ZIP سورس</h3><p>فایل سورس جدید نگاه مدیا را بارگذاری کنید. ابتدا ساختار، هش فایل‌ها و نگارش PHP بررسی می‌شود؛ پس از مشاهده تغییرات و تأیید رمز مدیر، نصب انجام می‌شود.</p><div class="notice success">اطلاعات سایت، پروژه‌ها، گالری‌ها، برندها، پیام‌ها، رمز مدیر، فونت و فایل‌های uploads بازنویسی نمی‌شوند.</div><div class="notice error">ZIP شامل کد اجرایی PHP است. فقط بسته‌ای را نصب کنید که خودتان ساخته‌اید یا از منبع مورد اعتماد گرفته‌اید. بررسی هش، امضای ناشر نیست و سالم یا قابل اعتماد بودن منطق کد را تضمین نمی‌کند.</div><ul class="help-list"><li>قبل از نصب، از فایل‌های کدِ در حال تغییر پشتیبان خصوصی گرفته می‌شود.</li><li>برای بازیابی کامل، جداگانه از data و uploads نیز پشتیبان بگیرید.</li><li>ZIP حداکثر ۵ مگابایت؛ حجم بازشده حداکثر ۴۰ مگابایت. مهلت تأیید هر بسته ۳۰ دقیقه است.</li><li>افزونه PHP ZIP و مجوز نوشتن روی فایل‌های کد و assets برای نصب ضروری است.</li><li>در خطای قابل مدیریت نصب، بازگردانی خودکار فایل‌های تغییرکرده انجام می‌شود؛ قطع فرایند یا خرابی سرور ممکن است به بازیابی دستی نیاز داشته باشد.</li></ul><?php if(is_file(__DIR__.'/data/update-maintenance.json')):?><div class="notice error">سایت در حالت نگهداری است. اگر نصب فعالی در جریان نیست، پشتیبان را بازیابی و سپس فایل data/update-maintenance.json را از سرور حذف کنید.</div><?php endif;?></div>
<?php if($pendingError):?><div class="notice error"><?=e($pendingError)?></div><?php endif;?>
<div class="admin-panel editor-form"><h3>۱. بارگذاری و بررسی بسته</h3><?php if(!class_exists('ZipArchive')):?><div class="notice error">افزونه ZIP در PHP فعال نیست؛ برای فعال‌سازی با مدیر سرور هماهنگ کنید.</div><?php else:?><form method="post" enctype="multipart/form-data" data-update-form><?php hidden('prepare_update');?><label>ZIP سورس نگاه مدیا<input type="file" name="source_zip" accept=".zip,application/zip" required></label><p class="admin-hint">از ZIP جدید negah-media-source.zip استفاده کنید؛ فایل negah-update.json باید داخل آن باشد. ZIP با پوشه اصلی یا بدون پوشه اصلی پشتیبانی می‌شود. فایل‌های داده داخل بسته فقط بررسی می‌شوند و روی سرور کپی نمی‌شوند.</p><button type="submit" class="button primary">بررسی فایل ZIP</button></form><?php endif;?></div>
<?php if($pending):?><div class="admin-panel editor-form"><h3>۲. تأیید و نصب</h3><dl class="update-summary"><div><dt>بسته</dt><dd><?=e($pending['name'])?></dd></div><div><dt>فایل قابل تغییر</dt><dd><?=count($pending['files'])?></dd></div><div><dt>فایل یکسان</dt><dd><?=$pending['unchanged']?></dd></div><div><dt>فایل محافظت‌شده / ابزار توسعه</dt><dd><?=$pending['ignored']?></dd></div></dl><div class="update-sha"><span>SHA-256 بسته</span><code><?=e($pending['sha256'])?></code></div><?php if($pending['files']):?><details class="update-file-list"><summary>فهرست فایل‌های جدید و تغییرکرده</summary><ul><?php foreach($pending['files'] as $path=>$hashes):?><li><code><?=e($path)?></code><span><?=$hashes['before']===null?'جدید':'تغییرکرده'?></span></li><?php endforeach;?></ul></details><form method="post" data-confirm="پس از تهیه پشتیبان، فایل‌های کد جایگزین شوند؟" data-update-form><?php hidden('install_update');?><input type="hidden" name="update_id" value="<?=e($pending['id'])?>"><label>رمز فعلی مدیر برای تأیید نصب<input type="password" name="update_password" autocomplete="current-password" required></label><label class="brand-check"><input type="checkbox" name="trust_package" value="1" required> منبع این سورس را می‌شناسم و نصب کد آن را تأیید می‌کنم.</label><button type="submit" class="button primary">پشتیبان‌گیری و نصب به‌روزرسانی</button></form><?php else:?><div class="notice success">کد این بسته با نسخه فعلی یکسان است؛ نیازی به نصب نیست.</div><?php endif;?><form method="post" class="reset-font"><?php hidden('discard_update');?><button class="button secondary">لغو و پاک‌کردن بسته موقت</button></form></div><?php endif;?>
<div class="admin-panel"><h3>نصب‌های انجام‌شده و پشتیبان‌ها</h3><?php if(!$history):?><p class="admin-hint">هنوز به‌روزرسانی‌ای از پنل نصب نشده است.</p><?php endif;?><?php foreach($history as $entry):?><div class="admin-project-row update-history-row"><div><b><?=e($entry['name'])?></b><small><time dir="ltr"><?=e($entry['date'])?></time> · <?=e($entry['count'])?> فایل · <?=e(['success'=>'نصب موفق','rolled_back'=>'نصب انجام نشد؛ کد بازگردانده شد','manual_recovery'=>'نیازمند بازیابی دستی'][$entry['status']]??'بررسی شود')?></small></div><form method="post"><?php hidden('download_update_backup');?><input type="hidden" name="backup_id" value="<?=e($entry['id'])?>"><button class="button secondary">دریافت پشتیبان کد قبلی</button></form></div><?php endforeach;?><p class="admin-hint">پشتیبان‌ها در data/updates/backups و خارج از دسترس عمومی نگهداری می‌شوند. ZIP پشتیبان فقط فایل‌های تغییرکرده و recovery.json را دارد، نه دیتای سایت. برای بازیابی دستی، فایل‌های قبلی را با دسترسی مدیر سرور جایگزین کنید و فایل‌های تازه‌ای را که در recovery.json مقدار before آن‌ها null است در صورت نیاز حذف کنید. این ZIP یک بسته نصب جدید نیست. پشتیبان‌های قدیمی را پس از دانلود، از سرور و با دسترسی مدیر پاک کنید.</p></div>
